input.command:
mkdir -p /tmp/gbrain-scripts && cat > /tmp/gbrain-scripts/mcp.ts <<'EOF'
// Minimal stdio MCP client: bun mcp.ts '<json array of [method, params]>'
const calls: [string, any][] = JSON.parse(process.argv[2]);
const proc = Bun.spawn(["/harness-state/.gbrain/hook-launcher/gbrain-hook", "/harness-state/.bun/bin/gbrain", "serve", "--surface", "starter", "--advertise", "verbs"],
  { stdin: "pipe", stdout: "pipe", stderr: "ignore" });
const reader = proc.stdout.getReader(); let buf = ""; const dec = new TextDecoder();
async function rpc(id: number, method: string, params: any) {
  proc.stdin.write(JSON.stringify({ jsonrpc: "2.0", id, method, params }) + "\n"); await proc.stdin.flush();
  while (true) {
    const nl = buf.indexOf("\n");
    if (nl >= 0) { const line = buf.slice(0, nl); buf = buf.slice(nl + 1); if (!line.trim()) continue;
      const m = JSON.parse(line); if (m.id === id) return m; continue; }
    const { value, done } = await reader.read(); if (done) throw new Error("server closed"); buf += dec.decode(value);
  }
}
await rpc(0, "initialize", { protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "install-check", version: "1" } });
proc.stdin.write(JSON.stringify({ jsonrpc: "2.0", method: "notifications/initialized" }) + "\n");
let id = 1;
for (const [method, params] of calls) {
  const r = await rpc(id++, method, params);
  console.log(`=== ${method} ${params?.name ?? ""}`);
  console.log(JSON.stringify(r.result ?? r.error, null, 1).slice(0, 2500));
}
proc.stdin.end(); proc.kill();
EOF
export PATH="$HOME/.bun/bin:$PATH"; cd /tmp && bun /tmp/gbrain-scripts/mcp.ts '[["tools/list",{}]]' | grep -E '"name"|=== '

